'use client'; import { useState } from 'react'; import { API } from '@/lib/api';
export default function SettingsForm({initial}:{initial:Record<string,string>}){const [saved,setSaved]=useState(false);const submit=async(e:React.FormEvent<HTMLFormElement>)=>{e.preventDefault();const body=Object.fromEntries(new FormData(e.currentTarget));const r=await fetch(`${API}/settings`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});setSaved(r.ok);};return <form onSubmit={submit} className="card max-w-3xl p-6"><h2 className="text-lg font-black">Store configuration</h2><p className="mt-1 text-sm text-muted">Manage global storefront values and manual-payment numbers from one place.</p><div className="mt-6 grid gap-4 sm:grid-cols-2">{[['storeName','Store name'],['tagline','Tagline'],['currency','Currency'],['freeShippingOver','Free shipping over'],['supportEmail','Support email'],['supportPhone','Support phone'],['facebook','Facebook URL'],['whatsapp','WhatsApp number'],['bkash','bKash payment number'],['nagad','Nagad payment number']].map(([name,label])=><label key={name}><span className="mb-2 block text-[10px] font-bold uppercase text-muted">{label}</span><input name={name} defaultValue={initial[name]||''} className="input"/></label>)}</div><button className="mt-6 rounded-lg bg-ink px-7 py-3 text-xs font-bold text-white">Save settings</button>{saved&&<span className="ml-4 text-xs font-bold text-green-700">Saved successfully</span>}</form>}
